            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] <= 3:
        bid = avg_prev * 1.2
    elif my_status['hp'] >= 7:
        bid = avg_prev * 0.8
    else:
        bid = avg_prev

    if day_context['supply'] < WATER_REQ * 2:
